package com.railbound.portal.assets;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.Optional;

/**
 * D-drive local media storage.
 *
 * <p>Keys are generated by the server, and every resolved path is re-checked to
 * stay inside the storage root. That blocks {@code ../} traversal even if a key
 * ever comes from an untrusted source.</p>
 */
@Service
public class LocalMediaStorage implements MediaStorage {

    private static final Logger log = LoggerFactory.getLogger(LocalMediaStorage.class);

    private final Path root;

    public LocalMediaStorage(@Value("${app.storage.local-root:local-data/media}") String rootPath) {
        this.root = Path.of(rootPath).toAbsolutePath().normalize();
        try {
            Files.createDirectories(root);
        } catch (IOException e) {
            throw new UncheckedIOException("Unable to create media storage root: " + root, e);
        }
        log.info("Local media storage root: {}", root);
    }

    @Override
    public String store(String key, byte[] data, String contentType) {
        Path target = resolveSafe(key);
        try {
            Files.createDirectories(target.getParent());
            Files.write(target, data);
            return key;
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to store media object: " + key, e);
        }
    }

    @Override
    public Optional<byte[]> read(String key) {
        Path target = resolveSafe(key);
        if (!Files.isRegularFile(target)) {
            return Optional.empty();
        }
        try {
            return Optional.of(Files.readAllBytes(target));
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to read media object: " + key, e);
        }
    }

    @Override
    public boolean exists(String key) {
        return Files.isRegularFile(resolveSafe(key));
    }

    /** Visible for validation: rejects keys that escape the storage root. */
    public Path resolveSafe(String key) {
        if (key == null || key.isBlank()) {
            throw new IllegalArgumentException("Media key is required");
        }
        Path resolved = root.resolve(key).normalize();
        if (!resolved.startsWith(root)) {
            throw new IllegalArgumentException("Media key escapes the storage root: " + key);
        }
        return resolved;
    }

    /** Test helper: writes a file directly, bypassing the upload token flow. */
    public void storeForTest(String key, byte[] data) {
        try {
            Path target = resolveSafe(key);
            Files.createDirectories(target.getParent());
            Files.copy(new java.io.ByteArrayInputStream(data), target, StandardCopyOption.REPLACE_EXISTING);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
